head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gPROCS_CD = '';
scwin.V_PROCS_CD_1 = '1'; // 검토
scwin.V_PROCS_CD_2 = '2'; // 승인
scwin.V_PROCS_CD_3 = '3'; // 유보
scwin.gEduApplSeq;
scwin.gEcrDiptProcsStatCd;
scwin.gDepCd = js_dep_cd;
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보

scwin.edu_appl_seq = frame.opener.scwin.edu_appl_seq;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        frame.width = 720;
        frame.height = 550;
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        await scwin.read();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16516.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Master_OnLoadCompleted
 * @description dts_Master 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Master_OnLoadCompleted = function(rowcount) {
    try {
        // fn_showProcButton( dts_Item.NameString(1, "HDCOM_DEP_CD" ), dts_Item.NameString(1, "LNK_DISCLS_PROCS_STAT_CD" ) );
        scwin.showProcButton(dts_Master.getCellData(1, "LECR_DIPT_PROCS_STAT_CD"), dts_Master.getCellData(1, "EDU_APPL_SEQ"), dts_Master.getCellData(1, "DEP_CD"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16516.dts_Master_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Cancel_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16516.btn_Cancel_onclick" });
    }
};

/**
 * @method
 * @name trs_Approve_OnSuccess
 * @description Approve On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Approve_OnSuccess = async function() {
    try {
        await $c.win.alert('정상처리되었습니다');
        await scwin.read();
        $c.frame.path("../").fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16516.trs_Approve_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Approve_OnFail
 * @description Approve On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Approve_OnFail = async function() {
    try {
        await $c.win.alert('처리가 실패하였습니다');
        await $c.win.alert(trs_Approve.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16516.trs_Approve_OnFail" });
    }
};

/**
 * @method
 * @name btn_Revwr_onclick
 * @description 「검토」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Revwr_onclick = async function() {
    try {
        await scwin.revwr();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16516.btn_Revwr_onclick" });
    }
};

/**
 * @method
 * @name btn_Approve_onclick
 * @description 「승인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Approve_onclick = async function() {
    try {
        await scwin.approve();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16516.btn_Approve_onclick" });
    }
};

/**
 * @method
 * @name btn_Reject_onclick
 * @description 「유보」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Reject_onclick = async function() {
    try {
        await scwin.reject();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16516.btn_Reject_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description 공문 개별조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    // 공문 개별조회

    const sbmOptions = {
        id : "sbm_dts_Master",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Master=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 교육기간
    const sbmOptions2 = {
        id : "sbm_dts_EDU_SCHDL",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_EDU_SCHDL=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description save 처리
 * @param {*} pType pType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function(pType) {
    let gMSG = '';
    if (pType === '10') {
        scwin.gPROCS_CD = scwin.V_PROCS_CD_1;
        gMSG = '검토';
    } else if (pType === '30') {
        scwin.gPROCS_CD = scwin.V_PROCS_CD_2;
        gMSG = '승인';
    } else if (pType === '40') {
        scwin.gPROCS_CD = scwin.V_PROCS_CD_3;
        gMSG = '유보';
    }
    const rtn = confirm(gMSG + ' 처리 하시겠습니까?');
    if (rtn === 1) {
        // if ( fn_getProcsSate(gPROCS_CD) == false ) {
        //    return false;
        // } else {
        trs_Approve.KeyName = "toinb_dataid4";
        // [전환검토] trs_Approve.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     EDU_APPL_SEQ : scwin.gEduApplSeq,
        //     LECR_DIPT_PROCS_STAT_CD : pType,
        //     EMP_NO : js_emp_no
        // };
        const sbmOptions = {
            id : "sbm_trs_Approve",
            action : "/ListedCompany.do",
            ref : "dts_Master",
            target : "trs_Approve=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        // }

    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name showProcButton
 * @description 처리버튼 생성여부
 * @param {String} pEcrDiptProcsStatCd pEcrDiptProcsStatCd
 * @param {*} pEduApplSeq pEduApplSeq
 * @param {String} pProcsDepCd pProcsDepCd
 * @returns {void}
 * @hidden N
 */
scwin.showProcButton = function(pEcrDiptProcsStatCd, pEduApplSeq, pProcsDepCd) {
    scwin.gEcrDiptProcsStatCd = pEcrDiptProcsStatCd;
    scwin.gEduApplSeq = pEduApplSeq;
    btn_Revwr.setBackgroundImage("../img/btn_study_d.gif");
    btn_Revwr.setDisabled(true);
    btn_Approve.setBackgroundImage("../img/btn_approval_d.gif");
    btn_Approve.setDisabled(true);
    btn_Reject.setBackgroundImage("../img/btn_reserve_d.gif");
    btn_Reject.setDisabled(true);
    panel_Button.hide();
    if (scwin.gEduApplSeq !== '') {
        // 00:미처리,10:검토,30:승인,40:유보
        if (scwin.gEcrDiptProcsStatCd === '00') {
            panel_Button.show("");
            // 팀장,당번 권한, 담당 부서원  팀장  : 09,   부서장: 40, 팀원: 03
            if (scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y' || scwin.gJobTitle === '09') {
                btn_Revwr.setBackgroundImage("../img/btn_study.gif");
                btn_Revwr.setDisabled(false);
                btn_Reject.setBackgroundImage("../img/btn_reserve.gif");
                btn_Reject.setDisabled(false);
            } else if (scwin.gDepCd === pProcsDepCd) {
                btn_Revwr.setBackgroundImage("../img/btn_study.gif");
                btn_Revwr.setDisabled(false);
                btn_Reject.setBackgroundImage("../img/btn_reserve.gif");
                btn_Reject.setDisabled(false);
            } else {
                panel_Button.hide();
            }
        } else if (scwin.gEcrDiptProcsStatCd === '10') {
            panel_Button.show("");

            // 팀장,당번 권한  팀장  : 09,   부서장: 40, 팀원: 03
            if (scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y' || scwin.gJobTitle === '09') {
                btn_Approve.setBackgroundImage("../img/btn_approval.gif");
                btn_Approve.setDisabled(false);
                btn_Reject.setBackgroundImage("../img/btn_reserve.gif");
                btn_Reject.setDisabled(false);
            } else {
                panel_Button.hide();
            }
        } else {
            panel_Button.hide();
        }
    }
};

/**
 * @method
 * @name revwr
 * @description 검토
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.revwr = async function() {
    await scwin.save('10');
};

/**
 * @method
 * @name approve
 * @description 승인
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.approve = async function() {
    await scwin.save('30');
};

/**
 * @method
 * @name reject
 * @description 유보
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reject = async function() {
    await scwin.save('40');
};
